use glam::DVec3;
use ingetrazo_gui::IngeTrazoApp;
use ingetrazo_core::{image_plane::{ImagePlane,ImagePickMode},layers::Layer,scene::SelectionItem,math::Ray};
use ingetrazo_tools::base::ToolContext;
fn vec(v:&serde_json::Value)->DVec3{DVec3::new(v[0].as_f64().unwrap(),v[1].as_f64().unwrap(),v[2].as_f64().unwrap())}
fn main(){let input:serde_json::Value=serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();let mut rows=serde_json::Map::new();for q in input.as_array().unwrap(){let mut a=IngeTrazoApp::new();a.system_clipboard=None;a.scene.layers.clear();for l in q["layers"].as_array().unwrap(){let mut layer=Layer::new(l["name"].as_str().unwrap());layer.visible=l["visible"].as_bool().unwrap();layer.locked=l["locked"].as_bool().unwrap();a.scene.layers.push(layer);}for p in q["images"].as_array().unwrap(){let mut image=ImagePlane::new("missing.png",vec(&p["origin"]),vec(&p["u"]),vec(&p["v"]));image.name=p["name"].as_str().unwrap().into();image.opacity=p["opacity"].as_f64().unwrap();image.layer=p["layer"].as_str().map(str::to_string);image.locked=p["locked"].as_bool().unwrap();a.scene.image_planes.push(image);}if q["face"].as_bool().unwrap(){a.scene.mesh.add_vertex(DVec3::ZERO);a.scene.mesh.add_vertex(DVec3::X*2.);a.scene.mesh.add_vertex(DVec3::Y*2.);a.scene.mesh.add_face(vec![0,1,2],vec![]);}for i in q["selected"].as_array().unwrap(){a.scene.select(SelectionItem::ImagePlane(i.as_u64().unwrap()as usize));}if let Some(action)=q["panel"].as_str(){if action=="hide"{a.set_layer_visibility(0,false);}else{a.set_layer_locked(0,true);}}let selected_before=a.scene.selection.iter().filter_map(|i|if let SelectionItem::ImagePlane(i)=i{Some(a.scene.image_planes[*i].name.clone())}else{None}).collect::<Vec<_>>();let ray=Ray::new(vec(&q["ray_origin"]),vec(&q["ray_dir"]));let picked=|mode|a.scene.image_plane_hit(&ray,mode).map(|(i,_)|a.scene.image_planes[i].name.clone());let mut row=serde_json::json!({"selected_before_click":selected_before,"inference":picked(ImagePickMode::Inference),"selectable":picked(ImagePickMode::Selectable),"locked_context":picked(ImagePickMode::LockedContext)});if !row["inference"].is_null()||q["face"].as_bool().unwrap(){let(point,normal)=ingetrazo_gui::viewport::cursor_work_plane(&a,&ray);row["workplane"]=serde_json::json!({"normal":normal,"constant":(point.as_vec3().dot(normal.as_vec3()))as f64});}let mode=q["modifiers"].as_str().unwrap();let ctx=ToolContext::with_modifiers(DVec3::ZERO,ray,mode.contains("shift"),mode.contains("ctrl"),false);a.dispatch_tool_click(&ctx);let name=|item:&SelectionItem|match item{SelectionItem::ImagePlane(i)=>a.scene.image_planes[*i].name.clone(),SelectionItem::Face(_)=>"Face".into(),_=>format!("{item:?}")};let mut selected=a.scene.selection.iter().map(name).collect::<Vec<_>>();selected.sort();row["selected"]=serde_json::json!(selected);let mut plain=a.scene.clone();plain.clear_selection();let mut tool=ingetrazo_tools::select::SelectTool::new();use ingetrazo_tools::base::Tool;tool.on_click(&mut plain,&ToolContext::new(DVec3::ZERO,ray));row["pick"]=plain.selection.iter().next().map(|item|serde_json::json!(name(item))).unwrap_or(serde_json::Value::Null);rows.insert(q["name"].as_str().unwrap().into(),row);}println!("{}",serde_json::to_string_pretty(&rows).unwrap());}
